/* From Uiverse.io by vinodjangid07 - Tags: input */
.__UIV_SCOPE__ .usernamelabel {
  display: block;
  color: white;
  font-size: 14px;
  padding: 5px 5px;
}

.__UIV_SCOPE__ #usernameField {
  display: block;
  width: 200px;
  height: 40px;
  background-color: #292929;
  border-radius: 30px;
  border: 2px solid #292929;
  padding: 0px 12px;
  outline: none;
  caret-color: rgb(152, 88, 255);
  color: rgb(212, 212, 212);
  font-size: 12px;
  transition-duration: .2s;
}

.__UIV_SCOPE__ #usernameField:focus,
.__UIV_SCOPE__ #usernameField:valid {
  border: 2px solid rgb(152, 88, 255);
  transition-duration: .2s;
}
